// Extract price, stock and campaign data from scraped content
const responseData = $input.all();
const competitor = $input.first();
const content = responseData[0].json.data;
const selectors = competitor.json.scraping_selectors;

let extractedData = {
  competitor_id: competitor.json.id,
  name: competitor.json.name,
  url: competitor.json.url,
  timestamp: new Date().toISOString()
};

try {
  // Parse selectors JSON
  const selectorConfig = JSON.parse(selectors || '{}');

  // Extract price using selector
  if (selectorConfig.price_selector) {
    const priceRegex = new RegExp(selectorConfig.price_selector, 'gi');
    const priceMatch = content.match(priceRegex);
    extractedData.price = priceMatch ? priceMatch[0].replace(/[^\d.,]/g, '') : null;
  }

  // Extract stock status
  if (selectorConfig.stock_selector) {
    const stockRegex = new RegExp(selectorConfig.stock_selector, 'gi');
    const stockMatch = content.match(stockRegex);
    extractedData.stock_status = stockMatch ? stockMatch[0].toLowerCase().includes('stokta') || stockMatch[0].toLowerCase().includes('available') : null;
  }

  // Extract campaign/promotion
  if (selectorConfig.campaign_selector) {
    const campaignRegex = new RegExp(selectorConfig.campaign_selector, 'gi');
    const campaignMatch = content.match(campaignRegex);
    extractedData.campaign = campaignMatch ? campaignMatch[0] : null;
  }

  // Add raw content for debugging
  extractedData.raw_content = content.substring(0, 1000);

} catch (error) {
  extractedData.error = error.message;
}

// Set last_checked timestamp
extractedData.last_checked = new Date().toISOString();

return { json: extractedData };

// Check for significant price changes
const currentData = $input.first();
const previousData = $input.all()[1];

if (!previousData || !previousData.json.price) {
  return { json: { alert: false, message: 'No previous data' } };
}

const currentPrice = parseFloat(currentData.json.price?.replace(/[^\d.,]/g, '').replace(',', '.')) || 0;
const previousPrice = parseFloat(previousData.json.price?.replace(/[^\d.,]/g, '').replace(',', '.')) || 0;

const priceChange = Math.abs(currentPrice - previousPrice);
const priceChangePercent = previousPrice > 0 ? (priceChange / previousPrice) * 100 : 0;

// Alert if price change is more than 5%
const alert = priceChangePercent > 5;

const alertData = {
  alert: alert,
  competitor_id: currentData.json.competitor_id,
  name: currentData.json.name,
  current_price: currentPrice,
  previous_price: previousPrice,
  price_change: priceChange,
  price_change_percent: priceChangePercent.toFixed(2),
  timestamp: currentData.json.timestamp
};

if (alert) {
  alertData.message = `⚠️ Fiyat Değişikliği Alert: ${currentData.json.name} - Fiyat %${priceChangePercent.toFixed(2)} değişti (${previousPrice} → ${currentPrice})`;
}

return { json: alertData };

