// Generate daily report
const data = $input.all();
const reportDate = new Date().toISOString().split('T')[0];

// Group data by competitor
const competitorData = {};
data.forEach(item => {
  const competitorId = item.json.competitor_id;
  if (!competitorData[competitorId]) {
    competitorData[competitorId] = {
      name: item.json.name,
      records: []
    };
  }
  competitorData[competitorId].records.push(item.json);
});

// Generate HTML report
let reportHtml = `
<!DOCTYPE html>
<html>
<head>
    <title>Günlük Rakip İzleme Raporu - ${reportDate}</title>
    <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        .header { background: #2c3e50; color: white; padding: 20px; border-radius: 5px; }
        .competitor { margin: 20px 0; padding: 15px; border: 1px solid #ddd; border-radius: 5px; }
        .price-change { color: #e74c3c; font-weight: bold; }
        .in-stock { color: #27ae60; }
        .out-of-stock { color: #e74c3c; }
        table { width: 100%; border-collapse: collapse; margin-top: 10px; }
        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
        th { background-color: #f2f2f2; }
    </style>
</head>
<body>
    <div class="header">
        <h1>📊 Günlük Rakip İzleme Raporu</h1>
        <p>Tarih: ${reportDate}</p>
        <p>Botfusions Dashboard</p>
    </div>
`;

// Add competitor sections
Object.keys(competitorData).forEach(competitorId => {
  const comp = competitorData[competitorId];
  const latest = comp.records[0];

  reportHtml += `
    <div class="competitor">
        <h2>${comp.name}</h2>
        <table>
            <tr>
                <th>Zaman</th>
                <th>Fiyat</th>
                <th>Stok Durumu</th>
                <th>Kampanya</th>
            </tr>
  `;

  comp.records.forEach(record => {
    const time = new Date(record.timestamp).toLocaleTimeString('tr-TR');
    const stockClass = record.stock_status ? 'in-stock' : 'out-of-stock';
    const stockText = record.stock_status ? 'Stokta' : 'Stokta Yok';

    reportHtml += `
            <tr>
                <td>${time}</td>
                <td>${record.price || 'Belirsiz'} ₺</td>
                <td class="${stockClass}">${stockText}</td>
                <td>${record.campaign || 'Yok'}</td>
            </tr>
    `;
  });

  reportHtml += `
        </table>
    </div>
  `;
});

reportHtml += `
</body>
</html>
`;

// Generate summary statistics
const totalCompetitors = Object.keys(competitorData).length;
const activeCompetitors = Object.values(competitorData).filter(comp => 
  comp.records.some(r => r.price && r.price !== 'Belirsiz')
).length;
const inStockCompetitors = Object.values(competitorData).filter(comp => 
  comp.records.some(r => r.stock_status)
).length;

// Add summary
reportHtml = reportHtml.replace('</body>', `
    <div class="header" style="margin-top: 30px;">
        <h2>📈 Özet İstatistikler</h2>
        <p><strong>Toplam Rakip:</strong> ${totalCompetitors}</p>
        <p><strong>Aktif Rakip (Fiyat Var):</strong> ${activeCompetitors}</p>
        <p><strong>Stokta Olan:</strong> ${inStockCompetitors}</p>
        <p><strong>Rapor Oluşturma Zamanı:</strong> ${new Date().toLocaleString('tr-TR')}</p>
    </div>
</body>
`);

const report = {
  date: reportDate,
  html_content: reportHtml,
  total_competitors: totalCompetitors,
  active_competitors: activeCompetitors,
  in_stock_competitors: inStockCompetitors,
  generated_at: new Date().toISOString()
};

return { json: report };
